// 簡易フィルタ（入力に含まれる文字で絞り込み）
    (function () {
      const input = document.getElementById('kanji-filter-input');
      const items = Array.from(document.querySelectorAll('.kanji-grid__item'));
      if (!input) return;
      input.addEventListener('input', () => {
        const q = input.value.trim();
        items.forEach(item => {
          const char = item.querySelector('.kanji-grid__char').textContent;
          item.style.display = !q || char.includes(q) ? '' : 'none';
        });
      });
    })();
